    if (input === null || input === undefined) {
      throw new Error('input is required.');
    }

    if (input.measuredAt !== undefined) {
      this.validateNonEmptyString(input.measuredAt, 'measuredAt');
    }
    if (input.glucoseValue !== undefined) {
      this.validateNumber(input.glucoseValue, 'glucoseValue');
    }
    if (input.unit !== undefined) {
      this.validateUnit(input.unit, 'unit');
    }
    if (input.note !== undefined) {
      this.validateString(input.note, 'note');
    }
  }

