    return { ...record };
  }

  private addRecordToPatientIndex(patientId: string, recordId: string): void {
    const recordIds: Set<string> | undefined = this.recordsByPatientId.get(patientId);
    if (recordIds !== undefined) {
      recordIds.add(recordId);
      return;
    }

    this.recordsByPatientId.set(patientId, new Set<string>([recordId]));
  }

  private removeRecordFromPatientIndex(patientId: string, recordId: string): void {
    const recordIds: Set<string> | undefined = this.recordsByPatientId.get(patientId);
    if (recordIds === undefined) {
      return;
    }

    recordIds.delete(recordId);
    if (recordIds.size === 0) {
      this.recordsByPatientId.delete(patientId);
    }
  }

