import type { GlucoseRecord, GlucoseRecordCreateInput, GlucoseRecordUpdateInput } from './types';

/**
 * In-memory repository for glucose measurement records.
 */
export class GlucoseRecordRepository {
  private readonly records: Map<string, GlucoseRecord> = new Map<string, GlucoseRecord>();

  /**
   * Lists all glucose records for a patient in insertion order.
   *
   * @param patientId - The patient identifier.
   * @returns A promise resolving to the matching glucose records.
   */
  public async list(patientId: string): Promise<GlucoseRecord[]> {
    this.validateNonEmptyString(patientId, 'patientId');

    const results: GlucoseRecord[] = [];
    for (const record of this.records.values()) {
      if (record.patientId === patientId) {
        results.push(this.cloneRecord(record));
      }
    }

    return results;
  }

  /**
   * Retrieves a glucose record by its identifier.
   *
   * @param id - The record identifier.
   * @returns A promise resolving to the record, or null when not found.
   */
  public async getById(id: string): Promise<GlucoseRecord | null> {
    this.validateNonEmptyString(id, 'id');

    const record: GlucoseRecord | undefined = this.records.get(id);
    return record === undefined ? null : this.cloneRecord(record);
  }

  /**
   * Creates a new glucose record.
   *
   * @param input - The record creation input.
   * @returns A promise resolving to the created record.
   */
  public async create(input: GlucoseRecordCreateInput): Promise<GlucoseRecord> {
    this.validateCreateInput(input);

    const now: string = new Date().toISOString();
    const id: string = this.generateId();
    const record: GlucoseRecord = {
      id,
      patientId: input.patientId,
      measuredAt: input.measuredAt,
      glucoseValue: input.glucoseValue,
      unit: input.unit,
      note: input.note,
      createdAt: now,
      updatedAt: now,
    };

    this.records.set(id, this.cloneRecord(record));
    return this.cloneRecord(record);
  }

  /**
   * Updates an existing glucose record.
   *
   * @param id - The record identifier.
   * @param input - The update input.
   * @returns A promise resolving to the updated record, or null when not found.
   */
  public async update(id: string, input: GlucoseRecordUpdateInput): Promise<GlucoseRecord | null> {
    this.validateNonEmptyString(id, 'id');
    this.validateUpdateInput(input);

    const existing: GlucoseRecord | undefined = this.records.get(id);
    if (existing === undefined) {
      return null;
    }

    const updated: GlucoseRecord = {
      ...existing,
      measuredAt: input.measuredAt === undefined ? existing.measuredAt : input.measuredAt,
      glucoseValue: input.glucoseValue === undefined ? existing.glucoseValue : input.glucoseValue,
      unit: input.unit === undefined ? existing.unit : input.unit,
      note: input.note === undefined ? existing.note : input.note,
      updatedAt: new Date().toISOString(),
    };

    this.records.set(id, this.cloneRecord(updated));
    return this.cloneRecord(updated);
  }

  /**
   * Deletes a glucose record by its identifier.
   *
   * @param id - The record identifier.
   * @returns A promise resolving to true when deleted, otherwise false.
   */
  public async delete(id: string): Promise<boolean> {
    this.validateNonEmptyString(id, 'id');
    return this.records.delete(id);
  }

  private validateCreateInput(input: GlucoseRecordCreateInput): void {
    this.validateRecordShape(input.patientId, input.measuredAt, input.glucoseValue, input.unit, 'input');
    if (input.note !== undefined) {
      this.validateOptionalString(input.note, 'input.note');
    }
  }

  private validateUpdateInput(input: GlucoseRecordUpdateInput): void {
    if (input.measuredAt !== undefined) {
      this.validateNonEmptyString(input.measuredAt, 'input.measuredAt');
    }
    if (input.glucoseValue !== undefined && !Number.isFinite(input.glucoseValue)) {
      throw new Error('input.glucoseValue must be a finite number.');
    }
    if (input.unit !== undefined && input.unit !== 'mmol/L' && input.unit !== 'mg/dL') {
      throw new Error("input.unit must be either 'mmol/L' or 'mg/dL'.");
    }
    if (input.note !== undefined) {
      this.validateOptionalString(input.note, 'input.note');
    }
  }

  private validateRecordShape(
    patientId: string,
    measuredAt: string,
    glucoseValue: number,
    unit: 'mmol/L' | 'mg/dL',
    parameterName: string,
  ): void {
    this.validateNonEmptyString(patientId, `${parameterName}.patientId`);
    this.validateNonEmptyString(measuredAt, `${parameterName}.measuredAt`);
    if (!Number.isFinite(glucoseValue)) {
      throw new Error(`${parameterName}.glucoseValue must be a finite number.`);
    }
    if (unit !== 'mmol/L' && unit !== 'mg/dL') {
      throw new Error(`${parameterName}.unit must be either 'mmol/L' or 'mg/dL'.`);
    }
  }

  private validateNonEmptyString(value: string, name: string): void {
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new Error(`${name} must be a non-empty string.`);
    }
  }

  private validateOptionalString(value: string, name: string): void {
    if (typeof value !== 'string') {
      throw new Error(`${name} must be a string.`);
    }
  }

  private cloneRecord(record: GlucoseRecord): GlucoseRecord {
    return { ...record };
  }

  private generateId(): string {
    const randomPart: string = Math.random().toString(36).slice(2, 10);
    const timestampPart: string = Date.now().toString(36);
    return `gr_${timestampPart}_${randomPart}`;
  }
}

