import {
  GlucoseRecord,
  GlucoseRecordCreateInput,
  GlucoseRecordUpdateInput,
} from './types';

/**
 * In-memory repository for glucose measurement records.
 */
export class GlucoseRecordRepository {
  private readonly records: Map<string, GlucoseRecord>;

  private readonly idGenerator: () => string;

  private readonly nowProvider: () => string;

  /**
   * Creates a new glucose record repository.
   *
   * @param idGenerator - Optional generator used to create record identifiers.
   * @param nowProvider - Optional provider used to create timestamps.
   */
  public constructor(
    idGenerator: () => string = GlucoseRecordRepository.generateId,
    nowProvider: () => string = GlucoseRecordRepository.getCurrentTimestamp,
  ) {
    this.records = new Map<string, GlucoseRecord>();
    this.idGenerator = idGenerator;
    this.nowProvider = nowProvider;
  }

  /**
   * Lists all records for a given patient.
   *
   * @param patientId - The patient identifier.
   * @returns A promise resolving to all matching glucose records.
   */
  public async list(patientId: string): Promise<GlucoseRecord[]> {
    if (patientId.length === 0) {
      return [];
    }

    return Array.from(this.records.values()).filter(
      (record: GlucoseRecord) => record.patientId === patientId,
    );
  }

  /**
   * Retrieves a record by its identifier.
   *
   * @param id - The record identifier.
   * @returns A promise resolving to the record, or null if not found.
   */
  public async getById(id: string): Promise<GlucoseRecord | null> {
    return this.records.get(id) ?? null;
  }

  /**
   * Creates a new glucose record.
   *
   * @param input - The data used to create the record.
   * @returns A promise resolving to the newly created glucose record.
   */
  public async create(input: GlucoseRecordCreateInput): Promise<GlucoseRecord> {
    const now: string = this.nowProvider();
    const id: string = this.createUniqueId();
    const record: GlucoseRecord = {
      id,
      patientId: input.patientId,
      measuredAt: input.measuredAt,
      glucoseValue: input.glucoseValue,
      unit: input.unit,
      note: input.note,
      createdAt: now,
      updatedAt: now,
    };

    this.records.set(id, record);
    return record;
  }

  /**
   * Updates an existing glucose record.
   *
   * @param id - The record identifier.
   * @param input - The fields to update.
   * @returns A promise resolving to the updated record, or null if not found.
   */
  public async update(
    id: string,
    input: GlucoseRecordUpdateInput,
  ): Promise<GlucoseRecord | null> {
    const existing: GlucoseRecord | undefined = this.records.get(id);
    if (existing === undefined) {
      return null;
    }

    const updated: GlucoseRecord = {
      ...existing,
      ...(input.measuredAt !== undefined ? { measuredAt: input.measuredAt } : {}),
      ...(input.glucoseValue !== undefined ? { glucoseValue: input.glucoseValue } : {}),
      ...(input.unit !== undefined ? { unit: input.unit } : {}),
      ...(input.note !== undefined ? { note: input.note } : {}),
      updatedAt: this.nowProvider(),
    };

    this.records.set(id, updated);
    return updated;
  }

  /**
   * Deletes a glucose record by identifier.
   *
   * @param id - The record identifier.
   * @returns A promise resolving to true when a record was deleted, otherwise false.
   */
  public async delete(id: string): Promise<boolean> {
    return this.records.delete(id);
  }

  private createUniqueId(): string {
    for (;;) {
      const id: string = this.idGenerator();
      if (!this.records.has(id)) {
        return id;
      }
    }
  }

  private static generateId(): string {
    const globalCrypto: Crypto | undefined = globalThis.crypto;
    if (globalCrypto !== undefined && typeof globalCrypto.randomUUID === 'function') {
      return globalCrypto.randomUUID();
    }

    return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  }

  private static getCurrentTimestamp(): string {
    return new Date().toISOString();
  }
}

