/**
 * In-memory repository for glucose measurement records.
 */
export class GlucoseRecordRepository {
  private readonly recordsById: Map<string, GlucoseRecord>;

  private readonly recordOrder: string[];

  private nextId: number;

  /**
   * Creates a new glucose record repository instance.
   */
  public constructor() {
    this.recordsById = new Map<string, GlucoseRecord>();
    this.recordOrder = [];
    this.nextId = 1;
  }

  /**
   * Returns all records for a given patient, ordered by creation time.
   */
  public async list(patientId: string): Promise<GlucoseRecord[]> {
    if (patientId.trim().length === 0) {
      return [];
    }

    const records: GlucoseRecord[] = [];
    for (const id of this.recordOrder) {
      const record: GlucoseRecord | undefined = this.recordsById.get(id);
      if (record !== undefined && record.patientId === patientId) {
        records.push({ ...record });
      }
    }

    return records;
  }

  /**
   * Returns a record by its identifier, or null when it does not exist.
   */
  public async getById(id: string): Promise<GlucoseRecord | null> {
    const record: GlucoseRecord | undefined = this.recordsById.get(id);
    return record === undefined ? null : { ...record };
  }

  /**
   * Creates a new glucose record.
   */
  public async create(input: GlucoseRecordCreateInput): Promise<GlucoseRecord> {
    const timestamp: string = new Date().toISOString();
    const id: string = String(this.nextId++);
    const record: GlucoseRecord = {
      id,
      patientId: input.patientId,
      measuredAt: input.measuredAt,
      glucoseValue: input.glucoseValue,
      unit: input.unit,
      note: input.note,
      createdAt: timestamp,
      updatedAt: timestamp,
    };

    this.recordsById.set(id, record);
    this.recordOrder.push(id);

    return { ...record };
  }

  /**
   * Updates an existing glucose record.
   */
  public async update(
    id: string,
    input: GlucoseRecordUpdateInput,
  ): Promise<GlucoseRecord | null> {
    const existing: GlucoseRecord | undefined = this.recordsById.get(id);
    if (existing === undefined) {
      return null;
    }

    const updated: GlucoseRecord = {
      ...existing,
      measuredAt: input.measuredAt ?? existing.measuredAt,
      glucoseValue: input.glucoseValue ?? existing.glucoseValue,
      unit: input.unit ?? existing.unit,
      note: input.note !== undefined ? input.note : existing.note,
      updatedAt: new Date().toISOString(),
    };

    this.recordsById.set(id, updated);
    return { ...updated };
  }

  /**
   * Deletes a glucose record by its identifier.
   */
  public async delete(id: string): Promise<boolean> {
    const existed: boolean = this.recordsById.delete(id);
    if (!existed) {
      return false;
    }

    const index: number = this.recordOrder.indexOf(id);
    if (index >= 0) {
      this.recordOrder.splice(index, 1);
    }

    return true;
  }
}

