import type {
  GlucoseRecord,
  GlucoseRecordCreateInput,
  GlucoseRecordUpdateInput,
} from './types';

/**
 * In-memory repository for glucose measurement records.
 */
export class GlucoseRecordRepository {
  private readonly records: Map<string, GlucoseRecord> = new Map<string, GlucoseRecord>();
  private idCounter: number = 0;

  /**
   * Lists all glucose records for a specific patient.
   *
   * @param patientId - The patient identifier.
   * @returns A promise resolving to the matching glucose records.
   */
  public async list(patientId: string): Promise<GlucoseRecord[]> {
    this.validateNonEmptyString(patientId, 'patientId');

    const result: GlucoseRecord[] = [];
    for (const record of this.records.values()) {
      if (record.patientId === patientId) {
        result.push(this.cloneRecord(record));
      }
    }

    return result;
  }

  /**
   * Retrieves a glucose record by its identifier.
   *
   * @param id - The record identifier.
   * @returns A promise resolving to the record, or null if not found.
   */
  public async getById(id: string): Promise<GlucoseRecord | null> {
    this.validateNonEmptyString(id, 'id');

    const record: GlucoseRecord | undefined = this.records.get(id);
    return record === undefined ? null : this.cloneRecord(record);
  }

  /**
   * Creates a new glucose record.
   *
   * @param input - The data used to create the record.
   * @returns A promise resolving to the created glucose record.
   */
  public async create(input: GlucoseRecordCreateInput): Promise<GlucoseRecord> {
    this.validateCreateInput(input);

    const now: string = this.createTimestamp();
    const record: GlucoseRecord = {
      id: this.generateId(),
      patientId: input.patientId,
      measuredAt: input.measuredAt,
      glucoseValue: input.glucoseValue,
      unit: input.unit,
      note: input.note,
      createdAt: now,
      updatedAt: now,
    };

    this.records.set(record.id, this.cloneRecord(record));
    return this.cloneRecord(record);
  }

  /**
   * Updates an existing glucose record.
   *
   * @param id - The record identifier.
   * @param input - The fields to update.
   * @returns A promise resolving to the updated record, or null if not found.
   */
  public async update(id: string, input: GlucoseRecordUpdateInput): Promise<GlucoseRecord | null> {
    this.validateNonEmptyString(id, 'id');
    this.validateUpdateInput(input);

    const existing: GlucoseRecord | undefined = this.records.get(id);
    if (existing === undefined) {
      return null;
    }

    const updated: GlucoseRecord = {
      ...existing,
      measuredAt: input.measuredAt !== undefined ? input.measuredAt : existing.measuredAt,
      glucoseValue: input.glucoseValue !== undefined ? input.glucoseValue : existing.glucoseValue,
      unit: input.unit !== undefined ? input.unit : existing.unit,
      note: input.note !== undefined ? input.note : existing.note,
      updatedAt: this.createTimestamp(),
    };

    this.records.set(id, this.cloneRecord(updated));
    return this.cloneRecord(updated);
  }

  /**
   * Deletes a glucose record by its identifier.
   *
   * @param id - The record identifier.
   * @returns A promise resolving to true if deleted, otherwise false.
   */
  public async delete(id: string): Promise<boolean> {
    this.validateNonEmptyString(id, 'id');
    return this.records.delete(id);
  }

  private generateId(): string {
    this.idCounter += 1;
    return `record_${this.idCounter}`;
  }

  private createTimestamp(): string {
    return new Date().toISOString();
  }

  private cloneRecord(record: GlucoseRecord): GlucoseRecord {
    return {
      id: record.id,
      patientId: record.patientId,
      measuredAt: record.measuredAt,
      glucoseValue: record.glucoseValue,
      unit: record.unit,
      note: record.note,
      createdAt: record.createdAt,
      updatedAt: record.updatedAt,
    };
  }

  private validateCreateInput(input: GlucoseRecordCreateInput): void {
    if (input === null || input === undefined) {
      throw new Error('input is required.');
    }

    this.validateNonEmptyString(input.patientId, 'input.patientId');
    this.validateNonEmptyString(input.measuredAt, 'input.measuredAt');
    this.validateNumber(input.glucoseValue, 'input.glucoseValue');
    this.validateUnit(input.unit, 'input.unit');
    if (input.note !== undefined) {
      this.validateString(input.note, 'input.note');
    }
  }

  private validateUpdateInput(input: GlucoseRecordUpdateInput): void {
    if (input === null || input === undefined) {
      throw new Error('input is required.');
    }

    if (input.measuredAt !== undefined) {
      this.validateNonEmptyString(input.measuredAt, 'input.measuredAt');
    }
    if (input.glucoseValue !== undefined) {
      this.validateNumber(input.glucoseValue, 'input.glucoseValue');
    }
    if (input.unit !== undefined) {
      this.validateUnit(input.unit, 'input.unit');
    }
    if (input.note !== undefined) {
      this.validateString(input.note, 'input.note');
    }
  }

  private validateUnit(unit: string, fieldName: string): void {
    if (unit !== 'mmol/L' && unit !== 'mg/dL') {
      throw new Error(`${fieldName} must be either 'mmol/L' or 'mg/dL'.`);
    }
  }

  private validateNumber(value: number, fieldName: string): void {
    if (typeof value !== 'number' || Number.isNaN(value) || !Number.isFinite(value)) {
      throw new Error(`${fieldName} must be a finite number.`);
    }
  }

  private validateString(value: string, fieldName: string): void {
    if (typeof value !== 'string') {
      throw new Error(`${fieldName} must be a string.`);
    }
  }

  private validateNonEmptyString(value: string, fieldName: string): void {
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new Error(`${fieldName} must be a non-empty string.`);
    }
  }
}

