   * @param id - The record identifier.
   * @param input - The update payload.
   * @returns The updated record, or null when not found.
   */
  public async update(id: string, input: GlucoseRecordUpdateInput): Promise<GlucoseRecord | null> {
    const existing: GlucoseRecord | undefined = recordsById.get(id);
    if (existing === undefined) {
      return null;
    }

    const updated: GlucoseRecord = {
      ...existing,
      measuredAt: input.measuredAt ?? existing.measuredAt,
      glucoseValue: input.glucoseValue ?? existing.glucoseValue,
      unit: input.unit ?? existing.unit,
      note: input.note !== undefined ? input.note : existing.note,
      updatedAt: new Date().toISOString(),
    };

    recordsById.set(id, updated);
    return cloneRecord(updated);
  }

  /**
   * Deletes a glucose record.
   *
   * @param id - The record identifier.
