import { describe, expect, it } from 'vitest';

import { GlucoseRecordHistoryService } from './history-service';
import type { GlucoseRecord } from './types';
import type { GlucoseRecordHistoryEvent } from './history-types';

/**
 * Creates a valid glucose record fixture.
 *
 * @param overrides - Properties to override on the default record.
 * @returns A glucose record fixture.
 */
function createRecord(overrides: Partial<GlucoseRecord> = {}): GlucoseRecord {
  return {
    id: 'record-1',
    patientId: 'patient-1',
    measuredAt: '2024-01-01T00:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
    ...overrides,
  };
}

/**
 * Extracts the action values from history events.
 *
 * @param events - The history events.
 * @returns The action values in order.
 */
function actionsOf(events: GlucoseRecordHistoryEvent[]): Array<'created' | 'updated' | 'deleted'> {
  return events.map((event: GlucoseRecordHistoryEvent) => event.action);
}

describe('GlucoseRecordHistoryService', () => {
  it('appendCreated/appendUpdated/appendDeleted add events', async () => {
    const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();

    const created: GlucoseRecord = createRecord({ id: 'record-1', patientId: 'patient-1' });
    const updatedBefore: GlucoseRecord = created;
    const updatedAfter: GlucoseRecord = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 125,
      measuredAt: '2024-01-01T01:00:00.000Z',
      updatedAt: '2024-01-01T01:00:00.000Z',
    });
    const deleted: GlucoseRecord = createRecord({
      id: 'record-2',
      patientId: 'patient-1',
      glucoseValue: 90,
      measuredAt: '2024-01-01T02:00:00.000Z',
      updatedAt: '2024-01-01T02:00:00.000Z',
    });

    service.appendCreated(created);
    service.appendUpdated(updatedBefore, updatedAfter);
    service.appendDeleted(deleted);

    const recordOneEvents: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-1');
    const recordTwoEvents: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-2');
    const patientEvents: GlucoseRecordHistoryEvent[] = await service.listAll('patient-1');

    expect(recordOneEvents).toHaveLength(2);
    expect(actionsOf(recordOneEvents)).toEqual(['created', 'updated']);
    expect(recordOneEvents[0]?.snapshot).toEqual(created);
    expect(recordOneEvents[1]?.snapshot).toEqual(updatedAfter);

    expect(recordTwoEvents).toHaveLength(1);
    expect(actionsOf(recordTwoEvents)).toEqual(['deleted']);
    expect(recordTwoEvents[0]?.snapshot).toEqual(deleted);

    expect(patientEvents).toHaveLength(3);
    expect(actionsOf(patientEvents)).toEqual(['created', 'updated', 'deleted']);
  });

  it("listByRecordId returns only the matching record's events", async () => {
    const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();

    service.appendCreated(createRecord({ id: 'record-a', patientId: 'patient-1' }));
    service.appendCreated(createRecord({ id: 'record-b', patientId: 'patient-1', glucoseValue: 111 }));
    service.appendUpdated(
      createRecord({ id: 'record-a', patientId: 'patient-1' }),
      createRecord({ id: 'record-a', patientId: 'patient-1', glucoseValue: 130 }),
    );
    service.appendDeleted(createRecord({ id: 'record-b', patientId: 'patient-1', glucoseValue: 111 }));

    const recordAEvents: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-a');
    const recordBEvents: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-b');

    expect(actionsOf(recordAEvents)).toEqual(['created', 'updated']);
    expect(recordAEvents.every((event: GlucoseRecordHistoryEvent) => event.recordId === 'record-a')).toBe(true);
    expect(recordAEvents[0]?.snapshot).toEqual(createRecord({ id: 'record-a', patientId: 'patient-1' }));
    expect(recordAEvents[1]?.snapshot).toEqual(createRecord({ id: 'record-a', patientId: 'patient-1', glucoseValue: 130 }));

    expect(actionsOf(recordBEvents)).toEqual(['created', 'deleted']);
    expect(recordBEvents.every((event: GlucoseRecordHistoryEvent) => event.recordId === 'record-b')).toBe(true);
  });

  it('listAll(patientId) returns events for a patient in insertion order', async () => {
    const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();

    service.appendCreated(createRecord({ id: 'record-a', patientId: 'patient-1' }));
    service.appendCreated(createRecord({ id: 'record-b', patientId: 'patient-2' }));
    service.appendUpdated(
      createRecord({ id: 'record-a', patientId: 'patient-1' }),
      createRecord({ id: 'record-a', patientId: 'patient-1', glucoseValue: 140 }),
    );
    service.appendDeleted(createRecord({ id: 'record-c', patientId: 'patient-1', glucoseValue: 88 }));
    service.appendUpdated(
      createRecord({ id: 'record-b', patientId: 'patient-2' }),
      createRecord({ id: 'record-b', patientId: 'patient-2', glucoseValue: 112 }),
    );

    const patientOneEvents: GlucoseRecordHistoryEvent[] = await service.listAll('patient-1');
    const patientTwoEvents: GlucoseRecordHistoryEvent[] = await service.listAll('patient-2');

    expect(actionsOf(patientOneEvents)).toEqual(['created', 'updated', 'deleted']);
    expect(patientOneEvents.map((event: GlucoseRecordHistoryEvent) => event.recordId)).toEqual([
      'record-a',
      'record-a',
      'record-c',
    ]);

    expect(actionsOf(patientTwoEvents)).toEqual(['created', 'updated']);
    expect(patientTwoEvents.map((event: GlucoseRecordHistoryEvent) => event.recordId)).toEqual([
      'record-b',
      'record-b',
    ]);
  });

  it('snapshots are preserved when supplied', async () => {
    const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();

    const created: GlucoseRecord = createRecord({
      id: 'record-snapshot',
      patientId: 'patient-1',
      glucoseValue: 101,
      note: 'initial note',
    });
    const updated: GlucoseRecord = createRecord({
      id: 'record-snapshot',
      patientId: 'patient-1',
      glucoseValue: 115,
      note: 'updated note',
