    for (const record of this.records.values()) {
      if (record.patientId === patientId) {
        results.push(this.cloneRecord(record));
      }
    }

    return results;
  }

  /**
   * Gets a glucose record by its identifier.
   *
   * @param id - The record identifier.
   * @returns A promise resolving to the record, or null when not found.
   */
  public async getById(id: string): Promise<GlucoseRecord | null> {
    this.validateNonEmptyString(id, 'id');
    const record: GlucoseRecord | undefined = this.records.get(id);
    return record === undefined ? null : this.cloneRecord(record);
  }

  /**
   * Creates a new glucose record.
   *
   * @param input - The record creation data.
   * @returns A promise resolving to the created record.
   */
  public async create(input: GlucoseRecordCreateInput): Promise<GlucoseRecord> {
    this.validateCreateInput(input);

    const now: string = new Date().toISOString();
    const record: GlucoseRecord = {
      id: this.generateId(),
      patientId: input.patientId,
      measuredAt: input.measuredAt,
      glucoseValue: input.glucoseValue,
      unit: input.unit,
      note: input.note,
      createdAt: now,
      updatedAt: now,
    };

    this.records.set(record.id, this.cloneRecord(record));
    return this.cloneRecord(record);
  }

  /**
   * Updates an existing glucose record.
   *
   * @param id - The record identifier.
   * @param input - The update data.
   * @returns A promise resolving to the updated record, or null when not found.
   */
  public async update(id: string, input: GlucoseRecordUpdateInput): Promise<GlucoseRecord | null> {
    this.validateNonEmptyString(id, 'id');
    this.validateUpdateInput(input);

    const existing: GlucoseRecord | undefined = this.records.get(id);
    if (existing === undefined) {
      return null;
    }

    const updated: GlucoseRecord = {
      ...existing,
      measuredAt: input.measuredAt !== undefined ? input.measuredAt : existing.measuredAt,
      glucoseValue: input.glucoseValue !== undefined ? input.glucoseValue : existing.glucoseValue,
      unit: input.unit !== undefined ? input.unit : existing.unit,
      note: input.note !== undefined ? input.note : existing.note,
      updatedAt: new Date().toISOString(),
    };

    this.records.set(id, this.cloneRecord(updated));
    return this.cloneRecord(updated);
