import { GlucoseRecord, GlucoseRecordCreateInput, GlucoseRecordUpdateInput } from './types';

/**
 * In-memory repository for glucose measurement records.
 */
export class GlucoseRecordRepository {
  private readonly records: Map<string, GlucoseRecord>;
  private nextId: number;

  /**
   * Creates a new repository instance.
   */
  public constructor() {
    this.records = new Map<string, GlucoseRecord>();
    this.nextId = 1;
  }

  /**
   * Lists all glucose records for a patient.
   *
   * @param patientId - Patient identifier.
   * @returns Matching records ordered by creation time.
   */
  public async list(patientId: string): Promise<GlucoseRecord[]> {
    if (patientId.length === 0) {
      return [];
    }

    return Array.from(this.records.values())
      .filter((record: GlucoseRecord) => record.patientId === patientId)
      .sort((left: GlucoseRecord, right: GlucoseRecord) => left.createdAt.localeCompare(right.createdAt));
  }

  /**
   * Retrieves a glucose record by id.
   *
   * @param id - Record identifier.
   * @returns The record if found, otherwise null.
   */
  public async getById(id: string): Promise<GlucoseRecord | null> {
    return this.records.get(id) ?? null;
  }

  /**
   * Creates a new glucose record.
   *
   * @param input - Creation payload.
   * @returns The persisted record.
   */
  public async create(input: GlucoseRecordCreateInput): Promise<GlucoseRecord> {
    const now: string = new Date().toISOString();
    const id: string = String(this.nextId);
    this.nextId += 1;

    const record: GlucoseRecord = {
      id,
      patientId: input.patientId,
      measuredAt: input.measuredAt,
      glucoseValue: input.glucoseValue,
      unit: input.unit,
      createdAt: now,
      updatedAt: now,
    };

    if (typeof input.note === 'string') {
      record.note = input.note;
    }

    this.records.set(id, record);
    return record;
  }

  /**
   * Updates an existing glucose record.
   *
   * @param id - Record identifier.
   * @param input - Partial update payload.
   * @returns The updated record, or null if not found.
   */
  public async update(id: string, input: GlucoseRecordUpdateInput): Promise<GlucoseRecord | null> {
    const existing: GlucoseRecord | undefined = this.records.get(id);
    if (existing === undefined) {
      return null;
    }

    const updated: GlucoseRecord = {
      ...existing,
      updatedAt: new Date().toISOString(),
    };

    if (input.measuredAt !== undefined) {
      updated.measuredAt = input.measuredAt;
    }
    if (input.glucoseValue !== undefined) {
      updated.glucoseValue = input.glucoseValue;
    }
    if (input.unit !== undefined) {
      updated.unit = input.unit;
    }
    if (input.note !== undefined) {
      updated.note = input.note;
    }

    this.records.set(id, updated);
    return updated;
  }

  /**
   * Deletes a glucose record by id.
   *
   * @param id - Record identifier.
   * @returns True when a record was removed.
   */
  public async delete(id: string): Promise<boolean> {
    return this.records.delete(id);
  }
}

