    measuredAt: '2024-01-01T10:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    note: 'fasting',
  });
  const second = await repository.create({
    patientId: 'patient-a',
    measuredAt: '2024-01-02T10:00:00.000Z',
    glucoseValue: 110,
    unit: 'mg/dL',
  });
  const third = await repository.create({
    patientId: 'patient-b',
    measuredAt: '2024-01-03T10:00:00.000Z',
    glucoseValue: 120,
    unit: 'mg/dL',
  });

  assert(first.id !== second.id && second.id !== third.id && first.id !== third.id, 'create should assign unique ids');
  assert(first.createdAt === first.updatedAt, 'create should set equal createdAt and updatedAt');
  assert(second.createdAt === second.updatedAt, 'create should set equal createdAt and updatedAt for every record');
  assert(first.createdAt.length > 0, 'create should set a timestamp');

  const patientARecords = await repository.list('patient-a');
  assert(patientARecords.length === 2, 'list(patientId) should return only matching records');
  assert(patientARecords[0].id === first.id && patientARecords[1].id === second.id, 'list should preserve insertion order for matching records');

  const emptyList = await repository.list('');
  assert(emptyList.length === 0, 'list should return empty array for empty patient id');

  const found = await repository.getById(first.id);
  assert(found !== null, 'getById should return a record when found');
  assert(found !== null && found.id === first.id, 'getById should return the correct record');

  const missing = await repository.getById('missing');
  assert(missing === null, 'getById should return null when missing');

  const beforeUpdate = await repository.getById(first.id);
  assert(beforeUpdate !== null, 'setup for update should retrieve record');
  const updated = await repository.update(first.id, {
    glucoseValue: 105,
    note: undefined,
  });
  assert(updated !== null, 'update should return the updated record');
  assert(updated !== null && updated.glucoseValue === 105, 'update should persist provided numeric fields');
