  assert(updated !== null && updated.unit === first.unit, 'update should keep unspecified unit unchanged');
  assert(updated !== null && updated.note === first.note, 'update should keep note unchanged when omitted');
  assert(updated !== null && updated.updatedAt !== first.updatedAt, 'update should refresh updatedAt');

  const afterUpdate = await repository.getById(first.id);
