import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { GlucoseRecordRepository } from './record-repository';

describe('GlucoseRecordRepository', () => {
  beforeEach((): void => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-10T12:00:00.000Z'));
  });

  afterEach((): void => {
    vi.useRealTimers();
  });

  it('create assigns unique ids and timestamps', async () => {
    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const first = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
      note: 'fasting',
    });

    const second = await repository.create({
      patientId: 'patient-b',
      measuredAt: '2024-01-02T08:00:00.000Z',
      glucoseValue: 110,
      unit: 'mg/dL',
    });

    expect(first.id).not.toBe(second.id);
    expect(first.createdAt).toBe('2024-01-10T12:00:00.000Z');
    expect(first.updatedAt).toBe('2024-01-10T12:00:00.000Z');
    expect(second.createdAt).toBe('2024-01-10T12:00:00.000Z');
    expect(second.updatedAt).toBe('2024-01-10T12:00:00.000Z');
  });

  it('list(patientId) returns only matching records', async () => {
    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const patientAFirst = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });
    const patientB = await repository.create({
      patientId: 'patient-b',
      measuredAt: '2024-01-02T08:00:00.000Z',
      glucoseValue: 110,
      unit: 'mg/dL',
    });
    const patientASecond = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-03T08:00:00.000Z',
      glucoseValue: 120,
      unit: 'mg/dL',
    });

    const patientARecords = await repository.list('patient-a');
    expect(patientARecords).toHaveLength(2);
    expect(patientARecords.map((record) => record.id)).toEqual([patientAFirst.id, patientASecond.id]);
    expect(patientARecords.every((record) => record.patientId === 'patient-a')).toBe(true);
    expect(patientARecords.some((record) => record.id === patientB.id)).toBe(false);

