    const updated = await repository.update(created.id, {
      glucoseValue: 125,
      unit: 'mmol/L',
    });

    assert(updated !== null, 'Expected update to return the updated record when it exists');
    assert(updated !== null && updated.patientId === created.patientId, 'Expected update to preserve unspecified fields');
    assert(updated !== null && updated.measuredAt === created.measuredAt, 'Expected update to preserve unspecified measuredAt');
    assert(updated !== null && updated.glucoseValue === 125, 'Expected update to persist provided glucoseValue');
    assert(updated !== null && updated.unit === 'mmol/L', 'Expected update to persist provided unit');
    assert(updated !== null && updated.note === 'before breakfast', 'Expected update to preserve note when omitted');
    assert(updated !== null && updated.updatedAt === '2024-01-10T12:30:00.000Z', 'Expected update to refresh updatedAt');

    const persisted = await repository.getById(created.id);
    assert(persisted !== null && persisted.glucoseValue === 125, 'Expected persisted record to reflect updated glucoseValue');
    assert(persisted !== null && persisted.unit === 'mmol/L', 'Expected persisted record to reflect updated unit');
    assert(persisted !== null && persisted.note === 'before breakfast', 'Expected persisted record to preserve omitted note');
    assert(persisted !== null && persisted.createdAt === created.createdAt, 'Expected createdAt to remain unchanged after update');
  });

  it('delete returns true when a record is removed and false otherwise', async () => {
    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const created = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });

    const deleted = await repository.delete(created.id);
    assert(deleted === true, 'Expected delete to return true when a record is removed');

    const deletedAgain = await repository.delete(created.id);
    assert(deletedAgain === false, 'Expected delete to return false when the record no longer exists');

    const afterDelete = await repository.getById(created.id);
    assert(afterDelete === null, 'Expected deleted record to no longer be retrievable');
  });
});

