import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { GlucoseRecordRepository } from './record-repository';
import type { GlucoseRecord } from './types';

/**
 * Asserts that a value is truthy.
 *
 * @param condition - The condition to validate.
 * @param message - The error message to print before exiting.
 */
function assert(condition: boolean, message: string): void {
  if (!condition) {
    console.error(message);
    process.exit(1);
  }
}

/**
 * Checks that two records contain the same persisted values.
 *
 * @param actual - The actual record.
 * @param expected - The expected record.
 */
function assertRecordEquals(actual: GlucoseRecord, expected: GlucoseRecord): void {
  assert(actual.id === expected.id, 'Expected ids to match');
  assert(actual.patientId === expected.patientId, 'Expected patientId to match');
  assert(actual.measuredAt === expected.measuredAt, 'Expected measuredAt to match');
  assert(actual.glucoseValue === expected.glucoseValue, 'Expected glucoseValue to match');
  assert(actual.unit === expected.unit, 'Expected unit to match');
  assert(actual.note === expected.note, 'Expected note to match');
  assert(actual.createdAt === expected.createdAt, 'Expected createdAt to match');
  assert(actual.updatedAt === expected.updatedAt, 'Expected updatedAt to match');
}

describe('GlucoseRecordRepository', () => {
  beforeEach((): void => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-10T12:00:00.000Z'));
  });

  afterEach((): void => {
    vi.useRealTimers();
  });

  it('create assigns unique ids and timestamps', async () => {
    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const first = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
      note: 'fasting',
    });

    const second = await repository.create({
      patientId: 'patient-b',
      measuredAt: '2024-01-02T08:00:00.000Z',
      glucoseValue: 110,
      unit: 'mg/dL',
    });

    assert(first.id !== second.id, 'Expected create to assign unique ids');
    assert(first.id === '1', 'Expected first created record to use id 1');
    assert(second.id === '2', 'Expected second created record to use id 2');
    assert(first.createdAt === '2024-01-10T12:00:00.000Z', 'Expected first createdAt timestamp to match system time');
    assert(first.updatedAt === '2024-01-10T12:00:00.000Z', 'Expected first updatedAt timestamp to match system time');
    assert(second.createdAt === '2024-01-10T12:00:00.000Z', 'Expected second createdAt timestamp to match system time');
    assert(second.updatedAt === '2024-01-10T12:00:00.000Z', 'Expected second updatedAt timestamp to match system time');
  });

  it('list(patientId) returns only matching records', async () => {
    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const patientAFirst = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });
    const patientB = await repository.create({
      patientId: 'patient-b',
      measuredAt: '2024-01-02T08:00:00.000Z',
      glucoseValue: 110,
      unit: 'mg/dL',
    });
    const patientASecond = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-03T08:00:00.000Z',
      glucoseValue: 120,
      unit: 'mg/dL',
    });

    const patientARecords = await repository.list('patient-a');
    assert(patientARecords.length === 2, 'Expected list to return only matching records');
    assert(patientARecords[0].id === patientAFirst.id, 'Expected list to preserve insertion order');
    assert(patientARecords[1].id === patientASecond.id, 'Expected list to preserve insertion order');
    assert(patientARecords.every((record: GlucoseRecord) => record.patientId === 'patient-a'), 'Expected all returned records to match patientId');
    assert(patientARecords.some((record: GlucoseRecord) => record.id === patientB.id) === false, 'Expected non-matching records to be excluded');

    const emptyRecords = await repository.list('');
    assert(emptyRecords.length === 0, 'Expected empty patientId to return an empty array');
  });

  it('getById returns a record or null', async () => {
    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const created = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
