describe('GlucoseRecordRepository', () => {
  it('create assigns unique ids and timestamps', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-10T12:00:00.000Z'));

    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const first = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
      note: 'fasting',
    });

    const second = await repository.create({
      patientId: 'patient-b',
      measuredAt: '2024-01-02T08:00:00.000Z',
      glucoseValue: 110,
      unit: 'mg/dL',
    });

    assert(first.id !== second.id, 'Expected create to assign unique ids');
    assert(first.id === '1', 'Expected first created record to use id 1');
    assert(second.id === '2', 'Expected second created record to use id 2');
    assert(first.createdAt === '2024-01-10T12:00:00.000Z', 'Expected createdAt to match the mocked system time');
    assert(first.updatedAt === '2024-01-10T12:00:00.000Z', 'Expected updatedAt to match the mocked system time');
    assert(second.createdAt === '2024-01-10T12:00:00.000Z', 'Expected createdAt to match the mocked system time');
    assert(second.updatedAt === '2024-01-10T12:00:00.000Z', 'Expected updatedAt to match the mocked system time');

    vi.useRealTimers();
  });

  it('list(patientId) returns only matching records', async () => {
    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const patientAFirst = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });
    const patientB = await repository.create({
      patientId: 'patient-b',
      measuredAt: '2024-01-02T08:00:00.000Z',
      glucoseValue: 110,
      unit: 'mg/dL',
    });
    const patientASecond = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-03T08:00:00.000Z',
      glucoseValue: 120,
      unit: 'mg/dL',
    });

    const patientARecords = await repository.list('patient-a');
    assert(patientARecords.length === 2, 'Expected list to return only matching records');
    assert(patientARecords[0].id === patientAFirst.id, 'Expected list to preserve insertion order');
    assert(patientARecords[1].id === patientASecond.id, 'Expected list to preserve insertion order');
    assert(patientARecords.every((record: GlucoseRecord) => record.patientId === 'patient-a'), 'Expected all returned records to match the patientId');
    assert(patientARecords.some((record: GlucoseRecord) => record.id === patientB.id) === false, 'Expected non-matching records to be excluded');

    const emptyRecords = await repository.list('');
    assert(emptyRecords.length === 0, 'Expected empty patientId to return an empty array');
  });

  it('getById returns a record or null', async () => {
    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const created = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
      note: 'before breakfast',
    });

    const found = await repository.getById(created.id);
    assert(found !== null, 'Expected getById to return a record when it exists');
    if (found === null) {
      process.exit(1);
    }
    assertRecordEquals(found, created);

    const missing = await repository.getById('missing-id');
    assert(missing === null, 'Expected getById to return null for missing records');
  });

  it('update persists only provided fields', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-10T12:00:00.000Z'));

    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const created = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
      note: 'before breakfast',
    });

    vi.setSystemTime(new Date('2024-01-10T12:30:00.000Z'));

    const updated = await repository.update(created.id, {
      glucoseValue: 125,
      unit: 'mmol/L',
    });

    assert(updated !== null, 'Expected update to return the updated record when it exists');
    if (updated === null) {
      process.exit(1);
    }
    assert(updated.patientId === created.patientId, 'Expected update to preserve unspecified fields');
    assert(updated.measuredAt === created.measuredAt, 'Expected update to preserve unspecified measuredAt');
    assert(updated.glucoseValue === 125, 'Expected update to persist provided glucoseValue');
    assert(updated.unit === 'mmol/L', 'Expected update to persist provided unit');
    assert(updated.note === 'before breakfast', 'Expected update to preserve note when omitted');
    assert(updated.updatedAt === '2024-01-10T12:30:00.000Z', 'Expected update to refresh updatedAt');

    const persisted = await repository.getById(created.id);
    assert(persisted !== null, 'Expected persisted record to exist after update');
    if (persisted === null) {
      process.exit(1);
    }
    assert(persisted.glucoseValue === 125, 'Expected persisted record to reflect updated glucoseValue');
    assert(persisted.unit === 'mmol/L', 'Expected persisted record to reflect updated unit');
    assert(persisted.note === 'before breakfast', 'Expected persisted record to preserve omitted note');
    assert(persisted.createdAt === created.createdAt, 'Expected createdAt to remain unchanged after update');

    vi.useRealTimers();
  });

  it('delete returns true when a record is removed and false otherwise', async () => {
    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const created = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });

    const deleted = await repository.delete(created.id);
    assert(deleted === true, 'Expected delete to return true when a record is removed');

    const deletedAgain = await repository.delete(created.id);
    assert(deletedAgain === false, 'Expected delete to return false when the record no longer exists');

    const afterDelete = await repository.getById(created.id);
    assert(afterDelete === null, 'Expected deleted record to no longer be retrievable');
  });
});

