import { describe, expect, it } from 'vitest';

import { GlucoseRecordService } from './record-service';
import type { GlucoseRecord, GlucoseRecordHistoryEvent } from './types';

/**
 * Creates a record fixture for assertions.
 *
 * @param overrides - Optional values to override.
 * @returns A glucose record fixture.
 */
function createRecordFixture(overrides: Partial<GlucoseRecord> = {}): GlucoseRecord {
  return {
    id: 'record-1',
    patientId: 'patient-1',
    measuredAt: '2024-01-01T08:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    note: 'fasting',
    createdAt: '2024-01-01T08:00:00.000Z',
    updatedAt: '2024-01-01T08:00:00.000Z',
    ...overrides,
  };
}

/**
 * Asserts a condition and exits the process on failure.
 *
 * @param condition - The condition to verify.
 * @param message - The failure message.
 */
function assert(condition: boolean, message: string): void {
  if (!condition) {
    console.error(message);
    process.exit(1);
  }
}

/**
 * Extracts the ordered actions from history events.
 *
 * @param events - The history events to inspect.
 * @returns The ordered history actions.
 */
function getActions(events: GlucoseRecordHistoryEvent[]): string {
  return events.map((event: GlucoseRecordHistoryEvent) => event.action).join(',');
}

/**
 * Verifies that all core record fields match.
 *
 * @param actual - The actual record.
 * @param expected - The expected record.
 */
function assertRecordMatches(actual: GlucoseRecord, expected: GlucoseRecord): void {
  assert(actual.id === expected.id, 'Expected ids to match');
  assert(actual.patientId === expected.patientId, 'Expected patientId to match');
  assert(actual.measuredAt === expected.measuredAt, 'Expected measuredAt to match');
  assert(actual.glucoseValue === expected.glucoseValue, 'Expected glucoseValue to match');
  assert(actual.unit === expected.unit, 'Expected unit to match');
  assert(actual.note === expected.note, 'Expected note to match');
  assert(actual.createdAt === expected.createdAt, 'Expected createdAt to match');
  assert(actual.updatedAt === expected.updatedAt, 'Expected updatedAt to match');
}

async function main(): Promise<void> {
  const service: GlucoseRecordService = new GlucoseRecordService();

  const created: GlucoseRecord = await service.createRecord({
    patientId: 'patient-1',
    measuredAt: '2024-01-01T08:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    note: 'fasting',
  });

  assert(created.id.length > 0, 'Expected createRecord to assign an id');
  assert(created.createdAt.length > 0, 'Expected createRecord to assign createdAt');
  assert(created.updatedAt.length > 0, 'Expected createRecord to assign updatedAt');
  assert(created.createdAt === created.updatedAt, 'Expected createRecord timestamps to match');
  assert(created.patientId === 'patient-1', 'Expected createRecord to preserve patientId');
  assert(created.measuredAt === '2024-01-01T08:00:00.000Z', 'Expected createRecord to preserve measuredAt');
  assert(created.glucoseValue === 100, 'Expected createRecord to preserve glucoseValue');
  assert(created.unit === 'mg/dL', 'Expected createRecord to preserve unit');
  assert(created.note === 'fasting', 'Expected createRecord to preserve note');

  const second: GlucoseRecord = await service.createRecord({
    patientId: 'patient-2',
    measuredAt: '2024-01-02T08:00:00.000Z',
    glucoseValue: 110,
    unit: 'mg/dL',
  });

  const patientOneRecords: GlucoseRecord[] = await service.listRecords('patient-1');
  assert(patientOneRecords.length === 1, 'Expected listRecords to filter by patientId');
  assertRecordMatches(patientOneRecords[0] as GlucoseRecord, created);

  const updated: GlucoseRecord | null = await service.updateRecord(created.id, {
    measuredAt: '2024-01-01T09:00:00.000Z',
    glucoseValue: 120,
    unit: 'mmol/L',
    note: 'after breakfast',
  });

  assert(updated !== null, 'Expected updateRecord to return the updated record');
  assert(updated !== null && updated.id === created.id, 'Expected updateRecord to keep the same id');
  assert(updated !== null && updated.patientId === created.patientId, 'Expected updateRecord to preserve patientId');
  assert(updated !== null && updated.measuredAt === '2024-01-01T09:00:00.000Z', 'Expected updateRecord to change measuredAt');
  assert(updated !== null && updated.glucoseValue === 120, 'Expected updateRecord to change glucoseValue');
  assert(updated !== null && updated.unit === 'mmol/L', 'Expected updateRecord to change unit');
  assert(updated !== null && updated.note === 'after breakfast', 'Expected updateRecord to change note');
  assert(updated !== null && updated.createdAt === created.createdAt, 'Expected updateRecord to preserve createdAt');
  assert(updated !== null && updated.updatedAt !== created.updatedAt, 'Expected updateRecord to change updatedAt');

  const fetchedAfterUpdate: GlucoseRecord | null = await service.getRecord(created.id);
  assert(fetchedAfterUpdate !== null, 'Expected getRecord to find the updated record');
  assert(
    fetchedAfterUpdate !== null && fetchedAfterUpdate.updatedAt === (updated as GlucoseRecord).updatedAt,
    'Expected getRecord to return latest updatedAt',
  );

  const deleted: boolean = await service.deleteRecord(created.id);
  assert(deleted, 'Expected deleteRecord to remove the record');

  const afterDelete: GlucoseRecord | null = await service.getRecord(created.id);
  assert(afterDelete === null, 'Expected deleted record to be missing');

  const remainingPatientOneRecords: GlucoseRecord[] = await service.listRecords('patient-1');
  assert(remainingPatientOneRecords.length === 0, 'Expected deleted record to be removed from listRecords results');

  const recordOneHistory: GlucoseRecordHistoryEvent[] = await service.getRecordHistory(created.id);
  assert(recordOneHistory.length === 3, 'Expected getRecordHistory to return created, updated, and deleted events');
  assert(getActions(recordOneHistory) === 'created,updated,deleted', 'Expected history events to be in order');
  assert(recordOneHistory[0]?.snapshot?.id === created.id, 'Expected created history event to reference the record');
  assert(recordOneHistory[1]?.snapshot?.id === created.id, 'Expected updated history event to reference the record');
  assert(recordOneHistory[2]?.snapshot?.id === created.id, 'Expected deleted history event to reference the record');

  const patientHistory: GlucoseRecordHistoryEvent[] = await service.listPatientHistory('patient-1');
  assert(patientHistory.length === 3, 'Expected listPatientHistory to include all events for the patient record');
  assert(getActions(patientHistory) === 'created,updated,deleted', 'Expected patient history to remain ordered');
  assert(patientHistory[0]?.snapshot?.patientId === 'patient-1', 'Expected patient history to filter by patientId');

  const patientTwoHistory: GlucoseRecordHistoryEvent[] = await service.listPatientHistory('patient-2');
  assert(patientTwoHistory.length === 1, 'Expected patient history to include events for the second patient');
  assert(patientTwoHistory[0]?.action === 'created', 'Expected second patient history to include the create event');
  assert(patientTwoHistory[0]?.snapshot?.id === second.id, 'Expected second patient history to reference the second record');

  console.log('PASS');
}

describe('GlucoseRecordService', () => {
  it('supports record lifecycle and history queries', async () => {
    await main();
  });
});

