import { afterEach, describe, it, vi } from 'vitest';

import { GlucoseRecordService } from './record-service';
import type { GlucoseRecord, GlucoseRecordHistoryEvent } from './types';

/**
 * Asserts that a condition is true.
 *
 * @param condition - The condition to verify.
 * @param message - The failure message.
 */
function assert(condition: boolean, message: string): void {
  if (!condition) {
    console.error(message);
    process.exit(1);
  }
}

/**
 * Creates a glucose record input fixture.
 *
 * @param overrides - Optional overrides.
 * @returns The record input fixture.
 */
function createInput(overrides: Partial<GlucoseRecord> = {}): {
  patientId: string;
  measuredAt: string;
  glucoseValue: number;
  unit: 'mmol/L' | 'mg/dL';
  note?: string;
} {
  return {
    patientId: 'patient-a',
    measuredAt: '2024-01-01T08:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    note: 'fasting',
    ...overrides,
  };
}

/**
 * Asserts that two records match on persisted fields.
 *
 * @param actual - The actual record.
 * @param expected - The expected record.
 */
function assertRecordMatches(actual: GlucoseRecord, expected: GlucoseRecord): void {
  assert(actual.id === expected.id, 'Expected ids to match');
  assert(actual.patientId === expected.patientId, 'Expected patientId to match');
  assert(actual.measuredAt === expected.measuredAt, 'Expected measuredAt to match');
  assert(actual.glucoseValue === expected.glucoseValue, 'Expected glucoseValue to match');
  assert(actual.unit === expected.unit, 'Expected unit to match');
  assert(actual.note === expected.note, 'Expected note to match');
  assert(actual.createdAt === expected.createdAt, 'Expected createdAt to match');
  assert(actual.updatedAt === expected.updatedAt, 'Expected updatedAt to match');
}

/**
 * Returns the action sequence for a set of history events.
 *
 * @param events - The history events.
 * @returns The ordered actions.
 */
function getActions(events: GlucoseRecordHistoryEvent[]): string {
  return events.map((event: GlucoseRecordHistoryEvent) => event.action).join(',');
}

/**
 * Restores real timers after each test.
 */
afterEach((): void => {
  vi.useRealTimers();
});

describe('GlucoseRecordService', () => {
  it('creates, lists, updates, deletes, and returns history in order', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));

    const service: GlucoseRecordService = new GlucoseRecordService();

    const createdOne: GlucoseRecord = await service.createRecord({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
      note: 'fasting',
    });

    assert(createdOne.id === '1', 'Expected createRecord to assign the first id');
    assert(createdOne.createdAt === '2024-01-01T00:00:00.000Z', 'Expected createdAt to use the current time');
    assert(createdOne.updatedAt === '2024-01-01T00:00:00.000Z', 'Expected updatedAt to use the current time');

    vi.advanceTimersByTime(1000);

    const createdTwo: GlucoseRecord = await service.createRecord({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T09:00:00.000Z',
      glucoseValue: 110,
      unit: 'mg/dL',
      note: 'before lunch',
    });

    vi.advanceTimersByTime(1000);

    const createdOtherPatient: GlucoseRecord = await service.createRecord({
      patientId: 'patient-b',
      measuredAt: '2024-01-01T10:00:00.000Z',
      glucoseValue: 120,
      unit: 'mmol/L',
    });

    const patientARecordsBeforeUpdate: GlucoseRecord[] = await service.listRecords('patient-a');
    assert(patientARecordsBeforeUpdate.length === 2, 'Expected listRecords to filter by patientId');
    assertRecordMatches(patientARecordsBeforeUpdate[0] as GlucoseRecord, createdOne);
    assertRecordMatches(patientARecordsBeforeUpdate[1] as GlucoseRecord, createdTwo);

    vi.advanceTimersByTime(1000);

    const updatedOne: GlucoseRecord | null = await service.updateRecord(createdOne.id, {
      measuredAt: '2024-01-01T08:30:00.000Z',
      glucoseValue: 105,
      unit: 'mmol/L',
      note: 'after walk',
    });

    assert(updatedOne !== null, 'Expected updateRecord to return the updated record');
    assert(updatedOne !== null && updatedOne.id === createdOne.id, 'Expected updateRecord to preserve id');
    assert(updatedOne !== null && updatedOne.patientId === createdOne.patientId, 'Expected updateRecord to preserve patientId');
    assert(updatedOne !== null && updatedOne.measuredAt === '2024-01-01T08:30:00.000Z', 'Expected updateRecord to change measuredAt');
    assert(updatedOne !== null && updatedOne.glucoseValue === 105, 'Expected updateRecord to change glucoseValue');
    assert(updatedOne !== null && updatedOne.unit === 'mmol/L', 'Expected updateRecord to change unit');
    assert(updatedOne !== null && updatedOne.note === 'after walk', 'Expected updateRecord to change note');
    assert(updatedOne !== null && updatedOne.createdAt === createdOne.createdAt, 'Expected updateRecord to preserve createdAt');
    assert(updatedOne !== null && updatedOne.updatedAt !== createdOne.updatedAt, 'Expected updateRecord to update updatedAt');
    assert(updatedOne !== null && updatedOne.updatedAt === '2024-01-01T00:00:03.000Z', 'Expected updateRecord to use the current time');

    const fetchedUpdatedOne: GlucoseRecord | null = await service.getRecord(createdOne.id);
    assert(fetchedUpdatedOne !== null, 'Expected getRecord to find the updated record');
    assert(fetchedUpdatedOne !== null, 'Expected getRecord result to be non-null');
    assertRecordMatches(fetchedUpdatedOne, updatedOne as GlucoseRecord);

    vi.advanceTimersByTime(1000);

    const deleted: boolean = await service.deleteRecord(createdOne.id);
    assert(deleted, 'Expected deleteRecord to remove the record');

    const deletedRecord: GlucoseRecord | null = await service.getRecord(createdOne.id);
    assert(deletedRecord === null, 'Expected deleted record to be missing');

    const patientARecordsAfterDelete: GlucoseRecord[] = await service.listRecords('patient-a');
    assert(patientARecordsAfterDelete.length === 1, 'Expected deleteRecord to remove the record from listRecords');
    assertRecordMatches(patientARecordsAfterDelete[0] as GlucoseRecord, createdTwo);

    const missingUpdate: GlucoseRecord | null = await service.updateRecord('missing-id', {
      glucoseValue: 130,
    });
    assert(missingUpdate === null, 'Expected updateRecord to return null for a missing record');

    const deletedMissing: boolean = await service.deleteRecord('missing-id');
    assert(!deletedMissing, 'Expected deleteRecord to return false for a missing record');

    const recordHistory: GlucoseRecordHistoryEvent[] = await service.getRecordHistory(createdOne.id);
    assert(recordHistory.length === 3, 'Expected getRecordHistory to return created, updated, and deleted events');
    assert(getActions(recordHistory) === 'created,updated,deleted', 'Expected history events to be returned in order');
    assert(recordHistory[0]?.snapshot?.id === createdOne.id, 'Expected created event to reference the record');
    assert(recordHistory[1]?.snapshot?.id === createdOne.id, 'Expected updated event to reference the record');
    assert(recordHistory[2]?.snapshot?.id === createdOne.id, 'Expected deleted event to reference the record');

    const patientHistory: GlucoseRecordHistoryEvent[] = await service.listPatientHistory('patient-a');
    assert(patientHistory.length === 4, 'Expected listPatientHistory to include all events for the patient');
    assert(getActions(patientHistory) === 'created,created,updated,deleted', 'Expected patient history to preserve event order');
    assert(patientHistory[0]?.recordId === createdOne.id, 'Expected first patient history event to belong to the first record');
    assert(patientHistory[1]?.recordId === createdTwo.id, 'Expected second patient history event to belong to the second record');
    assert(patientHistory[2]?.recordId === createdOne.id, 'Expected third patient history event to belong to the first record');
    assert(patientHistory[3]?.recordId === createdOne.id, 'Expected fourth patient history event to belong to the first record');

    const otherPatientHistory: GlucoseRecordHistoryEvent[] = await service.listPatientHistory('patient-b');
    assert(otherPatientHistory.length === 1, 'Expected listPatientHistory to filter by patient across all records');
    assert(otherPatientHistory[0]?.recordId === createdOtherPatient.id, 'Expected other patient history to reference the other patient record');
    assert(otherPatientHistory[0]?.action === 'created', 'Expected the other patient history to contain the create event');

    console.log('PASS');
  });
});

