import { afterEach, describe, expect, it, vi } from 'vitest';

import { GlucoseRecordService } from './record-service';
import type { GlucoseRecord, GlucoseRecordHistoryEvent } from './types';

/**
 * Restores real timers after each test.
 */
afterEach((): void => {
  vi.useRealTimers();
});

describe('GlucoseRecordService', () => {
  it('createRecord stores a record and returns id/timestamps', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));

    const service: GlucoseRecordService = new GlucoseRecordService();
    const created: GlucoseRecord = await service.createRecord({
      patientId: 'patient-1',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 98,
      unit: 'mg/dL',
      note: 'fasting',
    });

    expect(created.id).toBe('1');
    expect(created.createdAt).toBe('2024-01-01T00:00:00.000Z');
    expect(created.updatedAt).toBe('2024-01-01T00:00:00.000Z');

    const fetched: GlucoseRecord | null = await service.getRecord(created.id);
    expect(fetched).not.toBeNull();
    expect(fetched).toEqual(created);
  });

  it('listRecords filters by patientId', async () => {
    const service: GlucoseRecordService = new GlucoseRecordService();

    const patientA1: GlucoseRecord = await service.createRecord({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });
    const patientA2: GlucoseRecord = await service.createRecord({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T12:00:00.000Z',
      glucoseValue: 105,
      unit: 'mg/dL',
    });
    const patientB: GlucoseRecord = await service.createRecord({
      patientId: 'patient-b',
      measuredAt: '2024-01-01T09:00:00.000Z',
      glucoseValue: 110,
      unit: 'mmol/L',
    });

    const patientARecords: GlucoseRecord[] = await service.listRecords('patient-a');
    expect(patientARecords.length).toBe(2);
    expect(patientARecords[0]?.id).toBe(patientA1.id);
    expect(patientARecords[1]?.id).toBe(patientA2.id);
    expect(patientARecords.some((record: GlucoseRecord) => record.id === patientB.id)).toBe(false);
  });

  it('updateRecord changes editable fields and updates updatedAt', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));

    const service: GlucoseRecordService = new GlucoseRecordService();
    const created: GlucoseRecord = await service.createRecord({
      patientId: 'patient-1',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
      note: 'before breakfast',
    });

    vi.setSystemTime(new Date('2024-01-01T00:10:00.000Z'));
    const updated: GlucoseRecord | null = await service.updateRecord(created.id, {
      measuredAt: '2024-01-01T08:30:00.000Z',
      glucoseValue: 112,
      unit: 'mmol/L',
      note: 'after walking',
    });

    expect(updated).not.toBeNull();
    expect(updated?.id).toBe(created.id);
    expect(updated?.patientId).toBe(created.patientId);
    expect(updated?.measuredAt).toBe('2024-01-01T08:30:00.000Z');
    expect(updated?.glucoseValue).toBe(112);
    expect(updated?.unit).toBe('mmol/L');
    expect(updated?.note).toBe('after walking');
    expect(updated?.createdAt).toBe(created.createdAt);
    expect(updated?.updatedAt).toBe('2024-01-01T00:10:00.000Z');

    const fetched: GlucoseRecord | null = await service.getRecord(created.id);
    expect(fetched).toEqual(updated);
  });

  it('deleteRecord removes the record', async () => {
    const service: GlucoseRecordService = new GlucoseRecordService();
    const created: GlucoseRecord = await service.createRecord({
      patientId: 'patient-1',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });

    const deleted: boolean = await service.deleteRecord(created.id);
    expect(deleted).toBe(true);

    const fetched: GlucoseRecord | null = await service.getRecord(created.id);
    expect(fetched).toBeNull();

    const patientRecords: GlucoseRecord[] = await service.listRecords('patient-1');
    expect(patientRecords.length).toBe(0);
  });

  it('getRecordHistory returns created, updated, and deleted events in order', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));

    const service: GlucoseRecordService = new GlucoseRecordService();
    const created: GlucoseRecord = await service.createRecord({
      patientId: 'patient-1',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });

    vi.setSystemTime(new Date('2024-01-01T00:05:00.000Z'));
    await service.updateRecord(created.id, { glucoseValue: 108 });

    vi.setSystemTime(new Date('2024-01-01T00:10:00.000Z'));
    await service.deleteRecord(created.id);

    const history: GlucoseRecordHistoryEvent[] = await service.getRecordHistory(created.id);
    expect(history.map((event: GlucoseRecordHistoryEvent) => event.action)).toEqual([
      'created',
      'updated',
      'deleted',
    ]);
    expect(history.map((event: GlucoseRecordHistoryEvent) => event.recordId)).toEqual([
      created.id,
      created.id,
      created.id,
    ]);
    expect(history[0]?.snapshot?.glucoseValue).toBe(100);
    expect(history[1]?.snapshot?.glucoseValue).toBe(108);
    expect(history[2]?.snapshot?.glucoseValue).toBe(108);
  });

  it('listPatientHistory returns history for all records of the patient', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));

    const service: GlucoseRecordService = new GlucoseRecordService();
    const first: GlucoseRecord = await service.createRecord({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });

    vi.setSystemTime(new Date('2024-01-01T00:01:00.000Z'));
    const second: GlucoseRecord = await service.createRecord({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T09:00:00.000Z',
      glucoseValue: 120,
      unit: 'mg/dL',
    });

    vi.setSystemTime(new Date('2024-01-01T00:02:00.000Z'));
    await service.updateRecord(first.id, { glucoseValue: 101 });

    vi.setSystemTime(new Date('2024-01-01T00:03:00.000Z'));
    await service.deleteRecord(first.id);

    const patientHistory: GlucoseRecordHistoryEvent[] = await service.listPatientHistory('patient-a');
    expect(patientHistory.map((event: GlucoseRecordHistoryEvent) => event.action)).toEqual([
      'created',
      'created',
      'updated',
      'deleted',
    ]);
    expect(patientHistory.map((event: GlucoseRecordHistoryEvent) => event.recordId)).toEqual([
      first.id,
      second.id,
      first.id,
      first.id,
    ]);
  });
});

