import { afterEach, describe, it, vi } from 'vitest';

import { GlucoseRecordService } from './record-service';
import type { GlucoseRecord, GlucoseRecordHistoryEvent } from './history-types';
import type { GlucoseRecordCreateInput, GlucoseRecordUpdateInput } from './types';

function assert(condition: boolean, message: string): void {
  if (!condition) {
    console.error(message);
    process.exit(1);
  }
}

function assertEqual<T>(actual: T, expected: T, message: string): void {
  const actualJson: string = JSON.stringify(actual);
  const expectedJson: string = JSON.stringify(expected);
  assert(actualJson === expectedJson, `${message}\nExpected: ${expectedJson}\nActual:   ${actualJson}`);
}

/**
 * Restores real timers after each test.
 */
afterEach((): void => {
  vi.useRealTimers();
});

describe('GlucoseRecordService', () => {
  it('createRecord stores a record and returns id/timestamps', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));

    const service: GlucoseRecordService = new GlucoseRecordService();
    const input: GlucoseRecordCreateInput = {
      patientId: 'patient-1',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 98,
      unit: 'mg/dL',
      note: 'fasting',
    };

    const created: GlucoseRecord = await service.createRecord(input);

    assert(created.id === '1', 'Expected created record id to be "1".');
    assert(created.createdAt === '2024-01-01T00:00:00.000Z', 'Expected createdAt to match the frozen time.');
    assert(created.updatedAt === '2024-01-01T00:00:00.000Z', 'Expected updatedAt to match the frozen time.');

    const fetched: GlucoseRecord | null = await service.getRecord(created.id);
    assert(fetched !== null, 'Expected record to be retrievable after creation.');
    assertEqual(fetched, created, 'Expected stored record to match the created record.');
  });

  it('listRecords filters by patientId', async () => {
    const service: GlucoseRecordService = new GlucoseRecordService();

    const patientA1: GlucoseRecord = await service.createRecord({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });
    const patientA2: GlucoseRecord = await service.createRecord({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T12:00:00.000Z',
      glucoseValue: 105,
      unit: 'mg/dL',
    });
    const patientB: GlucoseRecord = await service.createRecord({
      patientId: 'patient-b',
      measuredAt: '2024-01-01T09:00:00.000Z',
      glucoseValue: 110,
      unit: 'mmol/L',
    });

    const patientARecords: GlucoseRecord[] = await service.listRecords('patient-a');
    assert(patientARecords.length === 2, 'Expected exactly two records for patient-a.');
    assert(patientARecords[0]?.id === patientA1.id, 'Expected first patient-a record to preserve insertion order.');
    assert(patientARecords[1]?.id === patientA2.id, 'Expected second patient-a record to preserve insertion order.');
    assert(!patientARecords.some((record: GlucoseRecord) => record.id === patientB.id), 'Expected patient-b record to be filtered out.');
  });

  it('updateRecord changes editable fields and updates updatedAt', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));

    const service: GlucoseRecordService = new GlucoseRecordService();
    const created: GlucoseRecord = await service.createRecord({
      patientId: 'patient-1',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
      note: 'before breakfast',
    });

    vi.setSystemTime(new Date('2024-01-01T00:10:00.000Z'));
    const updated: GlucoseRecord | null = await service.updateRecord(created.id, {
      measuredAt: '2024-01-01T08:30:00.000Z',
      glucoseValue: 112,
      unit: 'mmol/L',
      note: 'after walking',
    } satisfies GlucoseRecordUpdateInput);

    assert(updated !== null, 'Expected updateRecord to return the updated record.');
    assert(updated.id === created.id, 'Expected updated record id to remain unchanged.');
    assert(updated.patientId === created.patientId, 'Expected patientId to remain unchanged.');
    assert(updated.measuredAt === '2024-01-01T08:30:00.000Z', 'Expected measuredAt to update.');
    assert(updated.glucoseValue === 112, 'Expected glucoseValue to update.');
    assert(updated.unit === 'mmol/L', 'Expected unit to update.');
    assert(updated.note === 'after walking', 'Expected note to update.');
    assert(updated.createdAt === created.createdAt, 'Expected createdAt to remain unchanged.');
    assert(updated.updatedAt === '2024-01-01T00:10:00.000Z', 'Expected updatedAt to reflect the update time.');

    const fetched: GlucoseRecord | null = await service.getRecord(created.id);
    assertEqual(fetched, updated, 'Expected persisted record to match the updated record.');
  });

  it('deleteRecord removes the record', async () => {
    const service: GlucoseRecordService = new GlucoseRecordService();
    const created: GlucoseRecord = await service.createRecord({
      patientId: 'patient-1',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });

    const deleted: boolean = await service.deleteRecord(created.id);
    assert(deleted, 'Expected deleteRecord to return true for an existing record.');

    const fetched: GlucoseRecord | null = await service.getRecord(created.id);
    assert(fetched === null, 'Expected deleted record to no longer be retrievable.');

    const patientRecords: GlucoseRecord[] = await service.listRecords('patient-1');
    assert(patientRecords.length === 0, 'Expected deleted record to be removed from listRecords results.');
  });

  it('getRecordHistory returns created, updated, and deleted events in order', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));

    const service: GlucoseRecordService = new GlucoseRecordService();
    const created: GlucoseRecord = await service.createRecord({
      patientId: 'patient-1',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });

    vi.setSystemTime(new Date('2024-01-01T00:05:00.000Z'));
    await service.updateRecord(created.id, { glucoseValue: 108 });

    vi.setSystemTime(new Date('2024-01-01T00:10:00.000Z'));
    await service.deleteRecord(created.id);

    const history: GlucoseRecordHistoryEvent[] = await service.getRecordHistory(created.id);
    assertEqual(
      history.map((event: GlucoseRecordHistoryEvent) => event.action),
      ['created', 'updated', 'deleted'],
      'Expected history actions to be returned in chronological order.',
    );
    assertEqual(
      history.map((event: GlucoseRecordHistoryEvent) => event.recordId),
      [created.id, created.id, created.id],
      'Expected all history events to target the same record.',
    );
    assert(history[0]?.snapshot?.glucoseValue === 100, 'Expected created snapshot to reflect initial value.');
    assert(history[1]?.snapshot?.glucoseValue === 108, 'Expected updated snapshot to reflect updated value.');
    assert(history[2]?.snapshot?.glucoseValue === 108, 'Expected deleted snapshot to reflect final persisted value.');
  });

  it('listPatientHistory returns history for all records of the patient', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));

    const service: GlucoseRecordService = new GlucoseRecordService();
    const first: GlucoseRecord = await service.createRecord({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });

    vi.setSystemTime(new Date('2024-01-01T00:01:00.000Z'));
    const second: GlucoseRecord = await service.createRecord({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T09:00:00.000Z',
      glucoseValue: 120,
      unit: 'mg/dL',
    });

    vi.setSystemTime(new Date('2024-01-01T00:02:00.000Z'));
    await service.updateRecord(first.id, { glucoseValue: 101 });

    vi.setSystemTime(new Date('2024-01-01T00:03:00.000Z'));
    await service.deleteRecord(first.id);

    const patientHistory: GlucoseRecordHistoryEvent[] = await service.listPatientHistory('patient-a');
    assertEqual(
      patientHistory.map((event: GlucoseRecordHistoryEvent) => event.action),
      ['created', 'created', 'updated', 'deleted'],
      'Expected patient history to include all events for the patient in order.',
    );
    assertEqual(
      patientHistory.map((event: GlucoseRecordHistoryEvent) => event.recordId),
      [first.id, second.id, first.id, first.id],
      'Expected patient history to include events from both records.',
    );
  });
});

import { describe, it } from 'vitest';
import { GlucoseRecordRepository } from './record-repository';
import type { GlucoseRecord } from './types';

/**
 * Asserts that a condition is true.
 *
 * @param condition - The condition to verify.
 * @param message - The failure message.
 */
function assert(condition: boolean, message: string): void {
  if (!condition) {
    console.error(message);
    process.exit(1);
  }
}

/**
 * Asserts that two records match on all persisted fields.
 *
 * @param actual - The actual record.
 * @param expected - The expected record.
 */
function assertRecordMatches(actual: GlucoseRecord, expected: GlucoseRecord): void {
  assert(actual.id === expected.id, 'Expected ids to match');
  assert(actual.patientId === expected.patientId, 'Expected patientId to match');
  assert(actual.measuredAt === expected.measuredAt, 'Expected measuredAt to match');
  assert(actual.glucoseValue === expected.glucoseValue, 'Expected glucoseValue to match');
  assert(actual.unit === expected.unit, 'Expected unit to match');
  assert(actual.note === expected.note, 'Expected note to match');
  assert(actual.createdAt === expected.createdAt, 'Expected createdAt to match');
  assert(actual.updatedAt === expected.updatedAt, 'Expected updatedAt to match');
}

/**
 * Runs the create tests.
 */
async function testCreateAssignsUniqueIdsAndTimestamps(): Promise<void> {
  const repository: GlucoseRecordRepository = new GlucoseRecordRepository();
  const now: string = new Date().toISOString();

  const first: GlucoseRecord = await repository.create({
    patientId: 'patient-a',
    measuredAt: '2024-01-01T08:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    note: 'fasting',
  });
  const second: GlucoseRecord = await repository.create({
    patientId: 'patient-b',
    measuredAt: '2024-01-02T08:00:00.000Z',
    glucoseValue: 110,
    unit: 'mg/dL',
  });

  assert(first.id !== second.id, 'Expected create to assign unique ids');
  assert(first.id === '1', 'Expected first created record to use id 1');
  assert(second.id === '2', 'Expected second created record to use id 2');
  assert(first.createdAt === now, 'Expected createdAt to be set on create');
  assert(first.updatedAt === now, 'Expected updatedAt to be set on create');
  assert(second.createdAt === now, 'Expected createdAt to be set on create');
  assert(second.updatedAt === now, 'Expected updatedAt to be set on create');
}

/**
 * Runs the list tests.
 */
async function testListReturnsOnlyMatchingRecords(): Promise<void> {
  const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

  const patientAFirst: GlucoseRecord = await repository.create({
    patientId: 'patient-a',
    measuredAt: '2024-01-01T08:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
  });
  const patientB: GlucoseRecord = await repository.create({
    patientId: 'patient-b',
    measuredAt: '2024-01-02T08:00:00.000Z',
    glucoseValue: 110,
    unit: 'mg/dL',
  });
  const patientASecond: GlucoseRecord = await repository.create({
    patientId: 'patient-a',
    measuredAt: '2024-01-03T08:00:00.000Z',
    glucoseValue: 120,
    unit: 'mg/dL',
  });

  const patientARecords: GlucoseRecord[] = await repository.list('patient-a');
  assert(patientARecords.length === 2, 'Expected list to return only matching records');
  assert(patientARecords[0].id === patientAFirst.id, 'Expected list to preserve insertion order');
  assert(patientARecords[1].id === patientASecond.id, 'Expected list to preserve insertion order');
  assert(patientARecords.every((record: GlucoseRecord) => record.patientId === 'patient-a'), 'Expected all returned records to match the requested patient');
  assert(patientARecords.some((record: GlucoseRecord) => record.id === patientB.id) === false, 'Expected non-matching records to be excluded');

  const emptyRecords: GlucoseRecord[] = await repository.list('');
  assert(emptyRecords.length === 0, 'Expected empty patientId to return an empty array');
}

/**
 * Runs the getById tests.
 */
async function testGetByIdReturnsRecordOrNull(): Promise<void> {
  const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

  const created: GlucoseRecord = await repository.create({
    patientId: 'patient-a',
    measuredAt: '2024-01-01T08:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    note: 'before breakfast',
  });

  const found: GlucoseRecord | null = await repository.getById(created.id);
  assert(found !== null, 'Expected getById to return a record when it exists');
  if (found === null) {
    process.exit(1);
  }
  assertRecordMatches(found, created);

  const missing: GlucoseRecord | null = await repository.getById('missing-id');
  assert(missing === null, 'Expected getById to return null for missing records');
}

/**
 * Runs the update tests.
 */
async function testUpdatePersistsOnlyProvidedFields(): Promise<void> {
  const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

  const created: GlucoseRecord = await repository.create({
    patientId: 'patient-a',
    measuredAt: '2024-01-01T08:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    note: 'before breakfast',
  });

  const updated: GlucoseRecord | null = await repository.update(created.id, {
    glucoseValue: 125,
    unit: 'mmol/L',
  });

  assert(updated !== null, 'Expected update to return the updated record when it exists');
  if (updated === null) {
    process.exit(1);
  }
  assert(updated.patientId === created.patientId, 'Expected update to preserve unspecified fields');
  assert(updated.measuredAt === created.measuredAt, 'Expected update to preserve unspecified measuredAt');
  assert(updated.glucoseValue === 125, 'Expected update to persist provided glucoseValue');
  assert(updated.unit === 'mmol/L', 'Expected update to persist provided unit');
  assert(updated.note === 'before breakfast', 'Expected update to preserve note when omitted');
  assert(updated.createdAt === created.createdAt, 'Expected createdAt to remain unchanged after update');
  assert(updated.updatedAt !== created.updatedAt, 'Expected updatedAt to change after update');

  const persisted: GlucoseRecord | null = await repository.getById(created.id);
  assert(persisted !== null, 'Expected persisted record to exist after update');
  if (persisted === null) {
    process.exit(1);
  }
  assert(persisted.glucoseValue === 125, 'Expected persisted record to reflect updated glucoseValue');
  assert(persisted.unit === 'mmol/L', 'Expected persisted record to reflect updated unit');
  assert(persisted.note === 'before breakfast', 'Expected persisted record to preserve omitted note');
  assert(persisted.createdAt === created.createdAt, 'Expected createdAt to remain unchanged after update');
}

/**
