      assertDeepEqual(actionsOf(patientTwoEvents), ['created', 'updated'], 'Expected patient-2 events in insertion order.');
      assertDeepEqual(patientTwoEvents.map((event: GlucoseRecordHistoryEvent) => event.recordId), ['record-b', 'record-b'], 'Expected patient-2 record ids in insertion order.');
    });
  });

  it('snapshots are preserved when supplied', async () => {
    await runWithFakeTimers(async () => {
      const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();
      const created: GlucoseRecord = createRecord({ id: 'record-snapshot', patientId: 'patient-1', glucoseValue: 101, note: 'initial note' });
      const updated: GlucoseRecord = createRecord({ id: 'record-snapshot', patientId: 'patient-1', glucoseValue: 115, note: 'updated note', updatedAt: '2024-01-01T03:00:00.000Z' });
      const deleted: GlucoseRecord = createRecord({ id: 'record-snapshot', patientId: 'patient-1', glucoseValue: 115, note: 'updated note', updatedAt: '2024-01-01T04:00:00.000Z' });
      vi.setSystemTime(new Date('2024-01-01T00:00:00.000Z'));
      service.appendCreated(created);
      vi.setSystemTime(new Date('2024-01-01T00:00:01.000Z'));
      service.appendUpdated(created, updated);
      vi.setSystemTime(new Date('2024-01-01T00:00:02.000Z'));
      service.appendDeleted(deleted);
      const events: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-snapshot');
      assert(events.length === 3, 'Expected three snapshot events.');
      assertDeepEqual(events[0]?.snapshot, created, 'Expected created snapshot to be preserved.');
