 */
describe('GlucoseRecordRepository.delete', (): void => {
  it('returns true when a record is removed and false otherwise', async (): Promise<void> => {
    const repository: GlucoseRecordRepository = new GlucoseRecordRepository();

    const created: GlucoseRecord = await repository.create({
      patientId: 'patient-a',
      measuredAt: '2024-01-01T08:00:00.000Z',
      glucoseValue: 100,
      unit: 'mg/dL',
    });

    const deleted: boolean = await repository.delete(created.id);
    assert(deleted === true, 'Expected delete to return true when a record is removed');

    const deletedAgain: boolean = await repository.delete(created.id);
    assert(deletedAgain === false, 'Expected delete to return false when the record no longer exists');

    const afterDelete: GlucoseRecord | null = await repository.getById(created.id);
    assert(afterDelete === null, 'Expected deleted record to no longer be retrievable');
  });
});

