import { GlucoseRecordService } from './record-service';
import type { GlucoseRecord } from './types';

/**
 * View model for loading and sorting glucose measurement records.
 */
export class GlucoseRecordListViewModel {
  private readonly recordService: GlucoseRecordService;

  private lastPatientId: string | null;

  /**
   * Creates a new glucose record list view model.
   *
   * @param recordService - The glucose record service dependency.
   */
  public constructor(recordService: GlucoseRecordService = new GlucoseRecordService()) {
    this.recordService = recordService;
    this.lastPatientId = null;
  }

  /**
   * Loads records for the given patient and sorts them by measuredAt descending.
   *
   * @param patientId - The patient identifier.
   * @returns The sorted records.
   */
  public async load(patientId: string): Promise<GlucoseRecord[]> {
    this.validateNonEmptyString(patientId, 'patientId');
    this.lastPatientId = patientId;

    const records: GlucoseRecord[] = await this.recordService.listRecords(patientId);
    return this.sortByMeasuredAtDescending(records);
  }

  /**
   * Reloads records for the most recently loaded patient and sorts them by measuredAt descending.
   *
   * @returns The sorted records.
   */
  public async refresh(): Promise<GlucoseRecord[]> {
    if (this.lastPatientId === null) {
      throw new Error('No patient has been loaded yet.');
    }

    const records: GlucoseRecord[] = await this.recordService.listRecords(this.lastPatientId);
    return this.sortByMeasuredAtDescending(records);
  }

  /**
   * Sorts records by measuredAt in descending order without mutating the input array.
   *
   * @param records - The records to sort.
   * @returns A new array sorted by measuredAt descending.
   */
  public sortByMeasuredAtDescending(records: GlucoseRecord[]): GlucoseRecord[] {
    if (!Array.isArray(records)) {
      throw new Error('records must be an array.');
    }

    const clonedRecords: GlucoseRecord[] = records.map((record: GlucoseRecord) => ({ ...record }));
    clonedRecords.sort((left: GlucoseRecord, right: GlucoseRecord) => {
      const leftTime: number = Date.parse(left.measuredAt);
      const rightTime: number = Date.parse(right.measuredAt);

      if (Number.isNaN(leftTime) && Number.isNaN(rightTime)) {
        return 0;
      }
      if (Number.isNaN(leftTime)) {
        return 1;
      }
      if (Number.isNaN(rightTime)) {
        return -1;
      }

      return rightTime - leftTime;
    });

    return clonedRecords;
  }

  private validateNonEmptyString(value: string, parameterName: string): void {
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new Error(`${parameterName} must be a non-empty string.`);
    }
  }
}

import { GlucoseRecordListViewModel } from './record-list-view-model';
import { GlucoseRecordService } from './record-service';

async function main(): Promise<void> {
  const service: GlucoseRecordService = new GlucoseRecordService();
  const viewModel: GlucoseRecordListViewModel = new GlucoseRecordListViewModel(service);

  const createdOld = await service.createRecord({
    patientId: 'patient-1',
    measuredAt: '2024-01-01T08:00:00.000Z',
    glucoseValue: 5.2,
    unit: 'mmol/L',
  });
  const createdNew = await service.createRecord({
    patientId: 'patient-1',
    measuredAt: '2024-01-01T12:00:00.000Z',
    glucoseValue: 6.4,
    unit: 'mmol/L',
  });
  await service.createRecord({
    patientId: 'patient-2',
    measuredAt: '2024-01-01T09:00:00.000Z',
    glucoseValue: 7.1,
    unit: 'mg/dL',
  });

  const loaded = await viewModel.load('patient-1');
  if (loaded.length !== 2) {
    console.error('Expected load to return two records for patient-1.');
    process.exit(1);
  }
  if (loaded[0].id !== createdNew.id || loaded[1].id !== createdOld.id) {
    console.error('Expected load to sort records by measuredAt descending.');
    process.exit(1);
  }

  const refreshed = await viewModel.refresh();
  if (refreshed.length !== 2 || refreshed[0].id !== createdNew.id) {
    console.error('Expected refresh to reload the most recently loaded patient.');
    process.exit(1);
  }

  const original: Array<{ id: string; measuredAt: string }> = [
    { id: 'a', measuredAt: '2024-01-01T01:00:00.000Z' },
    { id: 'b', measuredAt: '2024-01-01T03:00:00.000Z' },
    { id: 'c', measuredAt: 'invalid-date' },
  ];
  const sorted = viewModel.sortByMeasuredAtDescending([
    {
      id: 'a',
      patientId: 'patient-1',
      measuredAt: '2024-01-01T01:00:00.000Z',
      glucoseValue: 1,
      unit: 'mmol/L',
      createdAt: '2024-01-01T01:00:00.000Z',
      updatedAt: '2024-01-01T01:00:00.000Z',
    },
    {
      id: 'b',
      patientId: 'patient-1',
      measuredAt: '2024-01-01T03:00:00.000Z',
      glucoseValue: 2,
      unit: 'mmol/L',
      createdAt: '2024-01-01T03:00:00.000Z',
      updatedAt: '2024-01-01T03:00:00.000Z',
    },
    {
      id: 'c',
      patientId: 'patient-1',
      measuredAt: 'invalid-date',
      glucoseValue: 3,
      unit: 'mg/dL',
      createdAt: '2024-01-01T04:00:00.000Z',
      updatedAt: '2024-01-01T04:00:00.000Z',
    },
  ]);

  if (sorted[0].id !== 'b' || sorted[1].id !== 'a' || sorted[2].id !== 'c') {
    console.error('Expected sortByMeasuredAtDescending to order valid dates first and invalid last.');
    process.exit(1);
  }

  if (original[0].id !== 'a' || original[1].id !== 'b' || original[2].id !== 'c') {
    console.error('Expected sortByMeasuredAtDescending to not mutate the input array reference.');
    process.exit(1);
  }

  const emptySorted = viewModel.sortByMeasuredAtDescending([]);
  if (emptySorted.length !== 0) {
    console.error('Expected sorting an empty array to return an empty array.');
    process.exit(1);
  }

  let threw: boolean = false;
  try {
    await new GlucoseRecordListViewModel(service).refresh();
  } catch {
    threw = true;
  }

  if (!threw) {
    console.error('Expected refresh to throw before any patient is loaded.');
    process.exit(1);
  }

  console.log('PASS');
}

main().catch((error: unknown) => {
  console.error(error);
  process.exit(1);
});

